:root {
  --bg: #1e1b4b;
  --card: #312e81;
  --text: #e0e7ff;
  --accent: #fbbf24;
  --accent-hover: #f59e0b;
  --accent-pressed: #d97706;
  --input-bg: #1e1b4b;
  --border: #6366f1;
  --error: #f87171;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  line-height: 1.5;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.subtitle {
  font-size: 0.95rem;
  margin-bottom: 24px;
  opacity: 0.85;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 1rem;
}

input {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--input-bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 8px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(251, 191, 36, 0.3);
}

input::placeholder {
  color: #a5b4fc;
  opacity: 0.7;
}

button {
  width: 100%;
  padding: 14px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: var(--font);
  background: var(--accent);
  color: #1e1b4b;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-top: 8px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.error {
  margin-top: 16px;
  padding: 12px;
  background: rgba(248, 113, 113, 0.15);
  border: 1px solid var(--error);
  border-radius: 8px;
  color: var(--error);
  font-weight: 600;
}

.result {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 2px solid var(--border);
}

h2 {
  font-size: 1.2rem;
  margin-bottom: 8px;
}

.change-amount {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 16px;
}

h3 {
  font-size: 1rem;
  margin-bottom: 8px;
  opacity: 0.9;
}

.breakdown {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.breakdown li {
  background: rgba(99, 102, 241, 0.2);
  padding: 8px 12px;
  border-radius: 6px;
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
}

.breakdown li span:first-child {
  font-weight: 600;
  color: var(--accent);
}

@media (max-width: 400px) {
  .breakdown {
    grid-template-columns: 1fr;
  }
  .card {
    padding: 24px 16px;
  }
}

const DENOMINATIONS = [20, 10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05];

const form = document.getElementById('change-form');
const priceInput = document.getElementById('price');
const paidInput = document.getElementById('paid');
const errorDiv = document.getElementById('error');
const resultSection = document.getElementById('result');
const changeAmountEl = document.getElementById('change-amount');
const breakdownList = document.getElementById('breakdown');

function showError(message) {
  errorDiv.textContent = message;
  errorDiv.hidden = false;
  resultSection.hidden = true;
}

function clearError() {
  errorDiv.hidden = true;
  errorDiv.textContent = '';
}

function formatMoney(value) {
  return '$' + value.toFixed(2);
}

function calculateChange(price, paid) {
  const change = Math.round((paid - price) * 100) / 100;
  let remaining = Math.round(change * 100);
  const breakdown = [];

  for (const denom of DENOMINATIONS) {
    const denomCents = Math.round(denom * 100);
    const count = Math.floor(remaining / denomCents);
    if (count > 0) {
      breakdown.push({ denom, count });
      remaining -= count * denomCents;
    }
  }

  return { change, breakdown };
}

function renderResult(change, breakdown) {
  changeAmountEl.textContent = formatMoney(change);
  breakdownList.innerHTML = '';

  if (breakdown.length === 0) {
    const li = document.createElement('li');
    li.textContent = 'No change needed.';
    li.style.gridColumn = '1 / -1';
    breakdownList.appendChild(li);
  } else {
    for (const item of breakdown) {
      const li = document.createElement('li');
      const label = document.createElement('span');
      label.textContent = item.denom >= 1 ? `$${item.denom}` : `${(item.denom * 100).toFixed(0)}c`;
      const countSpan = document.createElement('span');
      countSpan.textContent = `× ${item.count}`;
      li.appendChild(label);
      li.appendChild(countSpan);
      breakdownList.appendChild(li);
    }
  }

  resultSection.hidden = false;
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  clearError();

  const price = parseFloat(priceInput.value);
  const paid = parseFloat(paidInput.value);

  if (isNaN(price) || isNaN(paid)) {
    showError('Please enter valid numbers for both price and amount paid.');
    return;
  }

  if (price < 0 || paid < 0) {
    showError('Price and amount paid must be non-negative.');
    return;
  }

  if (paid < price) {
    showError('Amount paid must be at least the price.');
    return;
  }

  const { change, breakdown } = calculateChange(price, paid);
  renderResult(change, breakdown);
});

// Clear error when user types
priceInput.addEventListener('input', clearError);
paidInput.addEventListener('input', clearError);
